$writer->update('location')->fields(['country'=>'','city'=>'','street'=>'','postal_code'=>''])->condition('lid',1101)->execute();$reader->refresh();$adapter->destinations('hub',[1101]);[$v,$u]=$project->invoke($adapter,'hub',1101,Node::load(1101));$assert(!$u&&$v['en']['field_address']===[],'All-empty source address was not normalized');$passed[]='all-empty current address normalizes to an empty field';
